#if os(macOS)
import Foundation
import WispritEval

/// One recording script — the file a human reads aloud, parsed.
///
/// The synthetic corpus is generated by a zsh script whose lines are six
/// pipe-separated fields (`tools/eval/corpus/tts-samantha/generate.sh`). That
/// shape is right for a generator and wrong for a person: a reader must not be
/// able to read a field separator aloud by mistake, and the line on screen at
/// 2 a.m. should be exactly the sentence to say.
///
/// So a human script line is **the sentence to say**, optionally followed by
/// `|key=value` directives that the parser strips before the text is used:
///
///     Hi Sharique, please add this to Wisprit.|terms=Sharique,Wisprit
///     Ship it to 1600 Pennsylvania Avenue Northwest.|bypass=has_address
///     The payload is J-S-O-N, not YAML.|ref=The payload is JSON, not YAML.
///
/// `ref` is the one directive that is not an assertion: it is **the text the
/// user wanted in their document** when that differs from what a person reads
/// aloud (`docs/eval/DEFINITIONS.md`, "The reference"). It is needed far less
/// often than the synthetic script needs its `spoken | reference` pair, because
/// a human reads `3:15` as "three fifteen" and `sharique@gmail.com` as
/// "sharique at gmail dot com" without being told — a spelled run is the case
/// that genuinely has two forms. When absent, the reference *is* the line, which
/// is the common case and the reason the format is one column and not two.
///
/// A bare `|` in the sentence survives untouched — a suffix is a directive only
/// when it spells `|<lowercase-word>=`. A suffix with that shape whose key is
/// not one of the three is a **failure**, not text: `|term=Wisprit` is a typo
/// that would otherwise be read aloud and scored as part of the reference.
enum EvalScript {

    // MARK: - the parsed shape

    /// One utterance to record.
    struct Line: Equatable {
        /// `pn-01` — the category prefix and the 1-based index within the file.
        /// The manifest id adds the speaker and the microphone (see
        /// `EvalRecordPlan.manifestID`), because a corpus holds every speaker's
        /// take of this same line and ids must stay unique across all of them.
        var clipID: String
        var index: Int
        /// What the reader is shown and says. Lands in the manifest's `script`.
        var spoken: String
        /// What the document should contain — the scoreboard's reference.
        /// Equal to `spoken` unless the line carried `|ref=`.
        var ref: String
        /// `expect.terms`.
        var terms: [String]
        /// `expect.refineBypass`.
        var refineBypass: String?

        var expectation: CorpusExpectation? {
            guard !terms.isEmpty || refineBypass != nil else { return nil }
            return CorpusExpectation(terms: terms, refineBypass: refineBypass)
        }
    }

    /// A whole script file.
    struct File: Equatable {
        /// The `# category:` header — the scoreboard's per-category key.
        var category: String
        /// The id prefix derived from the category.
        var prefix: String
        /// The `#` comment block after the header, verbatim and in order. The
        /// recorder prints it once before the first line of the file: pace and
        /// distance directions are worthless in a README nobody has open while
        /// they are holding a microphone.
        var directions: [String]
        var lines: [Line]
    }

    // MARK: - failures

    enum ScriptError: Error, Equatable, CustomStringConvertible {
        case missingCategoryHeader(file: String)
        case badCategoryKey(file: String, value: String)
        case unknownDirective(file: String, line: Int, key: String)
        case duplicateDirective(file: String, line: Int, key: String)
        case emptyDirective(file: String, line: Int, key: String)
        case badBypass(file: String, line: Int, value: String)
        case emptyReference(file: String, line: Int)
        case noLines(file: String)
        case prefixCollision(prefix: String, categories: [String])

        var description: String {
            switch self {
            case let .missingCategoryHeader(file):
                return "\(file): first non-blank line must be '# category: <key>'"
            case let .badCategoryKey(file, value):
                return "\(file): category '\(value)' must be lowercase letters and hyphens"
            case let .unknownDirective(file, line, key):
                return "\(file):\(line): unknown directive '\(key)' "
                    + "(expected \(knownDirectives.sorted().joined(separator: "|")))"
            case let .duplicateDirective(file, line, key):
                return "\(file):\(line): directive '\(key)' given twice"
            case let .emptyDirective(file, line, key):
                return "\(file):\(line): directive '\(key)' has no value"
            case let .badBypass(file, line, value):
                return "\(file):\(line): bypass '\(value)' is not one of "
                    + knownBypasses.sorted().joined(separator: "|")
            case let .emptyReference(file, line):
                return "\(file):\(line): directives with nothing to read aloud in front of them"
            case let .noLines(file):
                return "\(file): no utterances"
            case let .prefixCollision(prefix, categories):
                return "categories \(categories.joined(separator: " and ")) "
                    + "both abbreviate to '\(prefix)' — rename one"
            }
        }
    }

    /// The only three directives. Anything else with the same shape is a typo
    /// and is refused rather than silently read aloud.
    static let knownDirectives: Set<String> = ["terms", "bypass", "ref"]

    /// The two `RefineOutcome` raw values an utterance can *assert* it left the
    /// cage with. Deliberately an allowlist rather than `RefineOutcome(rawValue:)`:
    /// `bypass=timeout` parses as a valid outcome and is meaningless as an
    /// expectation, and a script must not be able to record an expectation that
    /// can never be met on purpose.
    static let knownBypasses: Set<String> = ["has_address", "has_letter_run"]

    // MARK: - parsing

    /// Pure. `name` is only ever used to spell a failure.
    static func parse(_ text: String, name: String) throws -> File {
        var category: String?
        var directions: [String] = []
        var lines: [Line] = []

        for (offset, rawLine) in text.components(separatedBy: "\n").enumerated() {
            let number = offset + 1
            let trimmed = rawLine.trimmingCharacters(in: .whitespaces)
            if trimmed.isEmpty { continue }

            if trimmed.hasPrefix("#") {
                let comment = trimmed.dropFirst().trimmingCharacters(in: .whitespaces)
                if category == nil {
                    guard let key = headerValue(comment) else {
                        throw ScriptError.missingCategoryHeader(file: name)
                    }
                    guard isCategoryKey(key) else {
                        throw ScriptError.badCategoryKey(file: name, value: key)
                    }
                    category = key
                } else if !comment.isEmpty {
                    directions.append(comment)
                }
                continue
            }

            guard let category else { throw ScriptError.missingCategoryHeader(file: name) }
            let index = lines.count + 1
            lines.append(try line(trimmed, file: name, number: number,
                                  clipID: clipID(prefix: prefix(for: category), index: index),
                                  index: index))
        }

        guard let category else { throw ScriptError.missingCategoryHeader(file: name) }
        guard !lines.isEmpty else { throw ScriptError.noLines(file: name) }
        return File(category: category, prefix: prefix(for: category),
                    directions: directions, lines: lines)
    }

    /// `category: proper-nouns` → `proper-nouns`, anything else → nil.
    static func headerValue(_ comment: String) -> String? {
        guard let colon = comment.firstIndex(of: ":") else { return nil }
        let key = comment[comment.startIndex..<colon].trimmingCharacters(in: .whitespaces)
        guard key.lowercased() == "category" else { return nil }
        let value = comment[comment.index(after: colon)...].trimmingCharacters(in: .whitespaces)
        return value.isEmpty ? nil : value
    }

    static func isCategoryKey(_ value: String) -> Bool {
        !value.isEmpty
            && value.allSatisfy { ($0.isLowercase && $0.isLetter) || $0 == "-" }
            && !value.hasPrefix("-") && !value.hasSuffix("-")
    }

    static func line(_ raw: String, file: String, number: Int,
                     clipID: String, index: Int) throws -> Line {
        let (text, directives) = splitDirectives(raw)
        let spoken = text.trimmingCharacters(in: .whitespaces)
        guard !spoken.isEmpty else { throw ScriptError.emptyReference(file: file, line: number) }

        var terms: [String] = []
        var bypass: String?
        var reference: String?
        var seen = Set<String>()
        for (key, value) in directives {
            guard knownDirectives.contains(key) else {
                throw ScriptError.unknownDirective(file: file, line: number, key: key)
            }
            guard seen.insert(key).inserted else {
                throw ScriptError.duplicateDirective(file: file, line: number, key: key)
            }
            let trimmed = value.trimmingCharacters(in: .whitespaces)
            guard !trimmed.isEmpty else {
                throw ScriptError.emptyDirective(file: file, line: number, key: key)
            }
            switch key {
            case "terms":
                terms = trimmed.split(separator: ",")
                    .map { $0.trimmingCharacters(in: .whitespaces) }
                    .filter { !$0.isEmpty }
                guard !terms.isEmpty else {
                    throw ScriptError.emptyDirective(file: file, line: number, key: key)
                }
            case "ref":
                reference = trimmed
            default:
                guard knownBypasses.contains(trimmed) else {
                    throw ScriptError.badBypass(file: file, line: number, value: trimmed)
                }
                bypass = trimmed
            }
        }
        return Line(clipID: clipID, index: index, spoken: spoken, ref: reference ?? spoken,
                    terms: terms, refineBypass: bypass)
    }

    /// Peel `|key=value` suffixes off the right.
    ///
    /// Right-to-left and shape-gated: the scan stops at the first `|` whose tail
    /// does not spell `<lowercase-word>=`, so `The build is green | ship it`
    /// keeps its pipe and `…|terms=A,B|bypass=has_address` gives up both. Keys
    /// are returned in written order.
    static func splitDirectives(_ raw: String) -> (text: String, directives: [(String, String)]) {
        var text = Substring(raw)
        var found: [(String, String)] = []
        while let bar = text.lastIndex(of: "|") {
            let tail = text[text.index(after: bar)...]
            guard let equals = tail.firstIndex(of: "="),
                  isDirectiveKey(tail[tail.startIndex..<equals]) else { break }
            found.append((String(tail[tail.startIndex..<equals]),
                          String(tail[tail.index(after: equals)...])))
            text = text[text.startIndex..<bar]
        }
        return (String(text), found.reversed())
    }

    static func isDirectiveKey(_ value: Substring) -> Bool {
        !value.isEmpty && value.allSatisfy { $0.isLowercase && $0.isLetter }
    }

    // MARK: - names

    /// The category's abbreviation: initials of a hyphenated key, the first two
    /// letters of a single word. `proper-nouns` → `pn`, `homophones` → `ho`.
    ///
    /// Derived rather than declared so a new script file cannot forget one, and
    /// checked for collisions by `validate(_:)` — a derivation that can collide
    /// has to be able to say so.
    static func prefix(for category: String) -> String {
        let words = category.split(separator: "-")
        guard words.count > 1 else { return String(category.prefix(2)) }
        return words.compactMap(\.first).map(String.init).joined()
    }

    static func clipID(prefix: String, index: Int) -> String {
        "\(prefix)-\(String(format: "%02d", index))"
    }

    // MARK: - a whole directory

    /// Every `.txt` in `url`, in filename order.
    static func load(directory url: URL) throws -> [File] {
        let manager = FileManager.default
        let names = try manager.contentsOfDirectory(atPath: url.path)
            .filter { $0.hasSuffix(".txt") }
            .sorted()
        let files = try names.map { name -> File in
            let text = try String(contentsOf: url.appendingPathComponent(name), encoding: .utf8)
            return try parse(text, name: name)
        }
        try validate(files)
        return files
    }

    /// Two categories abbreviating to the same prefix would mint the same clip
    /// ids in two files. Pure, so the shipped scripts are checked by the test
    /// suite rather than by someone noticing a duplicate-id error mid-session.
    static func validate(_ files: [File]) throws {
        var byPrefix: [String: Set<String>] = [:]
        for file in files { byPrefix[file.prefix, default: []].insert(file.category) }
        for (prefix, categories) in byPrefix.sorted(by: { $0.key < $1.key })
        where categories.count > 1 {
            throw ScriptError.prefixCollision(prefix: prefix, categories: categories.sorted())
        }
    }
}
#endif
